from sqlalchemy import case, create_engine, select
from sqlalchemy.ext.hybrid import hybrid_property
from sqlalchemy.orm import DeclarativeBase, Mapped, Session, mapped_column


class Base(DeclarativeBase):
    pass


class Compte(Base):
    __tablename__ = "compte"
    id: Mapped[int] = mapped_column(primary_key=True)
    titulaire: Mapped[str]
    solde: Mapped[float]

    @hybrid_property
    def decouvert(self):
        return max(-self.solde, 0)

    @decouvert.inplace.expression
    @classmethod
    def _decouvert(cls):
        return case((cls.solde < 0, -cls.solde), else_=0)


engine = create_engine("sqlite://")
Base.metadata.create_all(engine)

with Session(engine) as session:
    session.add_all([Compte(titulaire="Camille", solde=120), Compte(titulaire="Karim", solde=-45)])
    session.commit()
    print(session.get(Compte, 2).decouvert)
    print(session.scalars(select(Compte.titulaire).where(Compte.decouvert > 0)).all())

