    derniers_chiffres: Mapped[str | None]
    __mapper_args__ = {"polymorphic_identity": "carte"}

    def frais(self):
        return round(self.montant * 0.015, 2)


class Virement(Paiement):
    iban: Mapped[str | None]
    __mapper_args__ = {"polymorphic_identity": "virement"}


