from sqlalchemy import create_engine, select
from sqlalchemy.orm import DeclarativeBase, Mapped, Session, mapped_column


class Base(DeclarativeBase):
    pass


class Paiement(Base):
    __tablename__ = "paiement"
    id: Mapped[int] = mapped_column(primary_key=True)
    montant: Mapped[float]
    type: Mapped[str]
    __mapper_args__ = {"polymorphic_on": "type", "polymorphic_identity": "paiement"}

    def frais(self):
        return 0.0


class Carte(Paiement):
    __mapper_args__ = {"polymorphic_identity": "carte"}

    def frais(self):
        return round(self.montant * 0.015, 2)


class Prelevement(Paiement):
    __mapper_args__ = {"polymorphic_identity": "prelevement"}

    def frais(self):
        return 0.5


engine = create_engine("sqlite://")
Base.metadata.create_all(engine)

with Session(engine) as session:
    session.add_all([Prelevement(montant=60), Carte(montant=100)])
    session.commit()
    print(sum(p.frais() for p in session.scalars(select(Paiement))))
